package de.fitnesscoach.ui.onboarding;

import android.content.Intent;import android.os.Bundle;import android.view.View;import android.widget.CheckBox;import androidx.activity.result.ActivityResultLauncher;import androidx.appcompat.app.AppCompatActivity;import androidx.health.connect.client.HealthConnectClient;import androidx.health.connect.client.contracts.HealthPermissionsRequestContract;import java.time.DayOfWeek;import java.util.*;import java.util.concurrent.*;import de.fitnesscoach.R;import de.fitnesscoach.data.db.FitnessCoachDatabase;import de.fitnesscoach.data.entity.*;import de.fitnesscoach.data.repository.ProfileRepository;import de.fitnesscoach.databinding.ActivityOnboardingBinding;import de.fitnesscoach.health.*;import de.fitnesscoach.ui.MainActivity;

public class OnboardingActivity extends AppCompatActivity{
 private ActivityOnboardingBinding binding;private OnboardingStateStore store;private HealthPermissionManager healthPermissionManager;private ActivityResultLauncher<Set<? extends String>> permissionLauncher;private final ExecutorService executor=Executors.newSingleThreadExecutor();private OnboardingStep step;
 @Override protected void onCreate(Bundle s){super.onCreate(s);store=new OnboardingStateStore(this);if(store.isCompleted()){openMain();return;}binding=ActivityOnboardingBinding.inflate(getLayoutInflater());setContentView(binding.getRoot());healthPermissionManager=new HealthPermissionManager(this);step=safeStep(store.getStep());permissionLauncher=registerForActivityResult(new HealthPermissionsRequestContract(HealthConnectClient.DEFAULT_PROVIDER_PACKAGE_NAME),g->render());restoreDraft();binding.onboardingBack.setOnClickListener(v->previous());binding.onboardingNext.setOnClickListener(v->next());binding.onboardingExit.setOnClickListener(v->finishAffinity());binding.onboardingHealthPermissions.setOnClickListener(v->requestHealthPermissions());render();}
 @Override protected void onDestroy(){super.onDestroy();executor.shutdownNow();}private OnboardingStep safeStep(int o){OnboardingStep[]v=OnboardingStep.values();return o<0||o>=v.length?OnboardingStep.WELCOME:v[o];}
 private void next(){binding.onboardingError.setVisibility(View.GONE);if(!persistAndValidateCurrentStep())return;if(step==OnboardingStep.COMPLETE){persistProfileAndFinish();return;}if(step==OnboardingStep.INITIAL_SYNC){runInitialSync();return;}step=OnboardingStep.values()[Math.min(step.ordinal()+1,OnboardingStep.COMPLETE.ordinal())];store.setStep(step.ordinal());render();}
 private void persistProfileAndFinish(){binding.onboardingNext.setEnabled(false);executor.execute(()->{ProfileRepository repo=new ProfileRepository(FitnessCoachDatabase.getInstance(this).profileDao());ProfileRepository.ProfileSnapshot old=repo.getSnapshot();UserProfileEntity p=old.profile==null?new UserProfileEntity():old.profile;p.fitnessLevel=DomainEnums.FitnessLevel.valueOf(store.getFitnessLevel());p.preferredSports=String.join(",",store.getSports());List<TrainingAvailabilityEntity>a=new ArrayList<>();Set<String>d=store.getAvailabilityDays();for(DayOfWeek day:DayOfWeek.values()){TrainingAvailabilityEntity x=new TrainingAvailabilityEntity();x.dayOfWeek=day.getValue();x.available=d.contains(day.name());x.maxDurationMinutes=x.available?store.getDurationMinutes():null;a.add(x);}repo.save(p,a);store.markCompleted();runOnUiThread(this::openMain);});}
 private void previous(){if(step.ordinal()==0)return;persistDraftWithoutValidation();step=OnboardingStep.values()[step.ordinal()-1];store.setStep(step.ordinal());render();}
 private boolean persistAndValidateCurrentStep(){switch(step){case FITNESS_LEVEL:String f=selectedFitnessLevel();if(!OnboardingValidator.hasFitnessLevel(f))return showError("Choose a fitness level to continue.");store.setFitnessLevel(f);return true;case SPORT_PREFERENCES:Set<String>s=selectedSports();if(!OnboardingValidator.hasSportPreference(s))return showError("Choose at least one activity.");store.setSports(s);return true;case TRAINING_AVAILABILITY:Set<String>d=selectedDays();int m=parsedDuration();if(!OnboardingValidator.hasTrainingAvailability(d,m))return showError("Choose at least one training day and enter a duration greater than zero.");store.setAvailabilityDays(d);store.setDurationMinutes(m);return true;case PRIMARY_GOAL:String g=binding.primaryGoal.getText().toString().trim();if(!OnboardingValidator.hasPrimaryGoal(g))return showError("Describe your primary fitness goal.");store.setPrimaryGoal(g);return true;default:return true;}}
 private void persistDraftWithoutValidation(){if(binding==null)return;String f=selectedFitnessLevel();if(!f.isEmpty())store.setFitnessLevel(f);Set<String>s=selectedSports();if(!s.isEmpty())store.setSports(s);Set<String>d=selectedDays();if(!d.isEmpty())store.setAvailabilityDays(d);int m=parsedDuration();if(m>0)store.setDurationMinutes(m);String g=binding.primaryGoal.getText().toString().trim();if(!g.isEmpty())store.setPrimaryGoal(g);}private boolean showError(String m){binding.onboardingError.setText(m);binding.onboardingError.setVisibility(View.VISIBLE);return false;}
 private void requestHealthPermissions(){Set<String>m=healthPermissionManager.getMissingRequiredPermissions();if(m.isEmpty())render();else permissionLauncher.launch(m);}private void runInitialSync(){HealthPermissionSnapshot s=healthPermissionManager.getSnapshot();if(!s.hasAnyRequiredGrant()){step=OnboardingStep.BASELINE_STATUS;store.setStep(step.ordinal());render();return;}binding.onboardingNext.setEnabled(false);binding.onboardingStatus.setVisibility(View.VISIBLE);binding.onboardingStatus.setText("Synchronizing Health Connect…");executor.execute(()->{HealthSyncResult r=new HealthSyncCoordinator(this).runSync();runOnUiThread(()->{if(binding==null)return;binding.onboardingNext.setEnabled(true);binding.onboardingStatus.setText(r.isSuccessful()?"Initial Health Connect synchronization completed.":"Synchronization failed. You can continue and retry later from Today.");step=OnboardingStep.BASELINE_STATUS;store.setStep(step.ordinal());render();});});}
 private void render(){if(binding==null)return;hideInputs();binding.onboardingProgress.setText("Setup "+(step.ordinal()+1)+" of "+OnboardingStep.values().length);binding.onboardingBack.setEnabled(step.ordinal()>0);binding.onboardingNext.setText(step==OnboardingStep.COMPLETE?"Finish":"Next");binding.onboardingExit.setVisibility(step.ordinal()<=OnboardingStep.HEALTH_CONNECT.ordinal()?View.VISIBLE:View.GONE);switch(step){case WELCOME:setText("Welcome","HealthAgentApp will become a personal running-focused fitness coach using your locally processed Health Connect data.");break;case COACH_BOUNDARIES:setText("Coach boundaries","The coach can help with training, recovery and sustainable goal progress. It is not a medical diagnostic or treatment service.");break;case FITNESS_LEVEL:setText("Fitness level","Choose the level that best describes your current training routine.");binding.fitnessLevelGroup.setVisibility(View.VISIBLE);break;case SPORT_PREFERENCES:setText("Sport preferences","Choose at least one activity.");binding.sportsGroup.setVisibility(View.VISIBLE);break;case TRAINING_AVAILABILITY:setText("Training availability","Select the days you normally have time and enter a typical maximum session duration.");binding.availabilityGroup.setVisibility(View.VISIBLE);break;case PRIMARY_GOAL:setText("Primary goal","Describe the main result you want the coach to optimize for.");binding.primaryGoal.setVisibility(View.VISIBLE);break;case HEALTH_CONNECT:setText("Health Connect","Grant only the health read permissions you are comfortable sharing. You can continue without access.");binding.onboardingHealthPermissions.setVisibility(View.VISIBLE);binding.onboardingStatus.setVisibility(View.VISIBLE);HealthPermissionSnapshot p=healthPermissionManager.getSnapshot();binding.onboardingStatus.setText(!p.isHealthConnectAvailable()?"Health Connect is unavailable on this device.":p.hasAnyRequiredGrant()?"At least one health data permission is granted.":"No health data permission granted yet.");break;case INITIAL_SYNC:setText("Initial synchronization","If Health Connect access is available, the app will now import available history.");binding.onboardingStatus.setVisibility(View.VISIBLE);HealthSyncStateEntity sync=FitnessCoachDatabase.getInstance(this).healthSyncDao().getState();binding.onboardingStatus.setText(sync!=null&&sync.lastSuccessfulSyncAt!=null?"Health data has already been synchronized successfully. Press Next to continue.":"Press Next to start the initial synchronization.");break;case BASELINE_STATUS:setText("Baseline status","Personal baselines are implemented in a later project step.");break;case INITIAL_PLAN:setText("Initial training plan","The deterministic running plan generator is implemented in a later project step.");break;case COMPLETE:setText("Setup complete","Your fitness profile and weekly availability will now be stored in the app database. Finish setup to open Today.");break;}}
 private void setText(String t,String b){binding.onboardingTitle.setText(t);binding.onboardingBody.setText(b);}private void hideInputs(){binding.fitnessLevelGroup.setVisibility(View.GONE);binding.sportsGroup.setVisibility(View.GONE);binding.availabilityGroup.setVisibility(View.GONE);binding.primaryGoal.setVisibility(View.GONE);binding.onboardingHealthPermissions.setVisibility(View.GONE);binding.onboardingStatus.setVisibility(View.GONE);binding.onboardingError.setVisibility(View.GONE);}
 private void restoreDraft(){String f=store.getFitnessLevel();if("BEGINNER".equals(f))binding.fitnessBeginner.setChecked(true);if("RECREATIONAL".equals(f))binding.fitnessRecreational.setChecked(true);if("REGULAR".equals(f))binding.fitnessRegular.setChecked(true);if("ADVANCED".equals(f))binding.fitnessAdvanced.setChecked(true);Set<String>s=store.getSports();binding.sportRunning.setChecked(s.contains("RUNNING"));binding.sportWalking.setChecked(s.contains("WALKING"));binding.sportCycling.setChecked(s.contains("CYCLING"));binding.sportStrength.setChecked(s.contains("STRENGTH"));Set<String>d=store.getAvailabilityDays();setDay(binding.dayMon,d,"MONDAY");setDay(binding.dayTue,d,"TUESDAY");setDay(binding.dayWed,d,"WEDNESDAY");setDay(binding.dayThu,d,"THURSDAY");setDay(binding.dayFri,d,"FRIDAY");setDay(binding.daySat,d,"SATURDAY");setDay(binding.daySun,d,"SUNDAY");binding.availabilityDuration.setText(String.valueOf(store.getDurationMinutes()));binding.primaryGoal.setText(store.getPrimaryGoal());}
 private String selectedFitnessLevel(){int id=binding.fitnessLevelGroup.getCheckedRadioButtonId();if(id==R.id.fitness_beginner)return"BEGINNER";if(id==R.id.fitness_recreational)return"RECREATIONAL";if(id==R.id.fitness_regular)return"REGULAR";if(id==R.id.fitness_advanced)return"ADVANCED";return"";}private Set<String>selectedSports(){Set<String>r=new LinkedHashSet<>();if(binding.sportRunning.isChecked())r.add("RUNNING");if(binding.sportWalking.isChecked())r.add("WALKING");if(binding.sportCycling.isChecked())r.add("CYCLING");if(binding.sportStrength.isChecked())r.add("STRENGTH");return r;}private Set<String>selectedDays(){Set<String>r=new LinkedHashSet<>();addDay(binding.dayMon,r,"MONDAY");addDay(binding.dayTue,r,"TUESDAY");addDay(binding.dayWed,r,"WEDNESDAY");addDay(binding.dayThu,r,"THURSDAY");addDay(binding.dayFri,r,"FRIDAY");addDay(binding.daySat,r,"SATURDAY");addDay(binding.daySun,r,"SUNDAY");return r;}private int parsedDuration(){try{return Integer.parseInt(binding.availabilityDuration.getText().toString().trim());}catch(Exception e){return 0;}}private void addDay(CheckBox b,Set<String>s,String v){if(b.isChecked())s.add(v);}private void setDay(CheckBox b,Set<String>s,String v){b.setChecked(s.contains(v));}private void openMain(){startActivity(new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_NEW_TASK));finish();}
}
